const TICKET='PEGA_TU_TICKET_MP';
const BASE='https://api2.mercadopublico.cl/v2/compra-agil';
const REGIONES='10,11,9';
let items=[],pagina=1,total=1,intentos=0;
while(pagina<=total && intentos<5){
  let r;
  try{
    r=await this.helpers.httpRequest({method:'GET',url:BASE,headers:{ticket:TICKET},qs:{ttl_cambio_ms:43200000,region:REGIONES,estado:'publicada',tamano_pagina:50,numero_pagina:pagina}});
  }catch(e){
    if(String(e.message).includes('429')){intentos++;await new Promise(s=>setTimeout(s,5000));continue;}
    throw e;
  }
  if(r.success!=='OK'||!r.payload||!r.payload.items) throw new Error('API: '+JSON.stringify(r.errors));
  total=r.payload.paginacion.total_paginas;
  items.push(...r.payload.items);
  intentos=0;pagina++;
  if(pagina<=total) await new Promise(s=>setTimeout(s,2000));
}
const filtered=items.filter(i=>(i.montos&&i.montos.monto_disponible_clp?i.montos.monto_disponible_clp:0)>0);
console.log('Compras con monto > 0: '+filtered.length);
return filtered.map(i=>({json:i}));

const URL='https://ugbyawltzcahjjjgnkid.supabase.co';
const KEY='PEGA_TU_SERVICE_ROLE_KEY';
const out=[];
for(const it of $input.all().map(i=>i.json)){
  const inst=it.institucion||{};
  const fc=it.fechas&&it.fechas.fecha_cierre?it.fechas.fecha_cierre.split(' ')[0]:null;
  const fp=it.fechas&&it.fechas.fecha_publicacion?it.fechas.fecha_publicacion.split(' ')[0]:null;
  const row={codigo:String(it.codigo),nombre:it.nombre||'',organismo:inst.organismo_comprador||'',unidad_compra:inst.unidad_compra||'',region:inst.nombre_region||'',monto_clp:(it.montos&&it.montos.monto_disponible_clp)?it.montos.monto_disponible_clp:null,fecha_cierre:fc,fecha_publicacion:fp,url_mp:'https://www.mercadopublico.cl/Procurement/Modules/RFB/DetailsAcquisition.aspx?idlicitacion='+it.codigo,raw:it};
  try{
    const resp=await this.helpers.httpRequest({method:'POST',url:URL+'/rest/v1/opportunities?on_conflict=codigo',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=representation'},body:[row]});
    const saved=Array.isArray(resp)?resp[0]:resp;
    out.push({json:{opportunity_id:saved.id,codigo:row.codigo,nombre:row.nombre,organismo:row.organismo,region:row.region,monto_clp:row.monto_clp,fecha_cierre:row.fecha_cierre}});
  }catch(e){ console.error('Upsert '+it.codigo+': '+e.message); }
}
console.log('Oportunidades guardadas/actualizadas: '+out.length);
return out;

