const URL='https://ugbyawltzcahjjjgnkid.supabase.co';
const KEY='PEGA_TU_SERVICE_ROLE_KEY';
const usuarios=$input.all().map(i=>i.json);
const compras=$('Guardar Oportunidades').all().map(i=>i.json);
const ex=await this.helpers.httpRequest({method:'GET',url:URL+'/rest/v1/user_opportunities?select=user_id,opportunity_id',headers:{apikey:KEY,Authorization:'Bearer '+KEY}});
const ya=new Set((ex||[]).map(r=>r.user_id+'|'+r.opportunity_id));
const out=[];
for(const u of usuarios){
  for(const c of compras){
    if(ya.has(u.user_id+'|'+c.opportunity_id)) continue;
    const m=Number(c.monto_clp)||0;
    if(u.monto_min!=null && m<u.monto_min) continue;
    if(u.monto_max!=null && m>u.monto_max) continue;
    const montoTxt=m?('$'+m.toLocaleString('es-CL')+' CLP'):'No informado';
    const up=`Analiza esta Compra Ágil y devuelve SOLO JSON:

CÓDIGO: ${c.codigo}
NOMBRE: ${c.nombre}
ORGANISMO: ${c.organismo}
REGIÓN: ${c.region}
MONTO: ${montoTxt}
CIERRE: ${c.fecha_cierre||'No disponible'}

JSON (sin markdown): {"score":<0-100>,"viabilidad":"alta|media|baja","resumen":"<2 lineas>","justificacion":"<3 lineas>","riesgo":"<1 linea>","accion":"cotizar|investigar|ignorar","precio_sugerido_clp":<numero o null>}`;
    out.push({json:{user_id:u.user_id,opportunity_id:c.opportunity_id,codigo:c.codigo,score_minimo:(u.score_minimo!=null?u.score_minimo:40),system_message:u.system_message||'Eres un asistente que evalúa compras públicas de Chile. Devuelve SOLO JSON.',user_prompt:up}});
  }
}
console.log('Pares usuario x compra a evaluar: '+out.length);
return out;

const URL='https://ugbyawltzcahjjjgnkid.supabase.co';
const KEY='PEGA_TU_SERVICE_ROLE_KEY';
const inputs=$input.all();
const ctx=$('Cruzar Usuario x Compra').all();
const res=[];
for(let i=0;i<inputs.length;i++){
  const j=inputs[i].json;
  const raw=(j.output!=null)?j.output:((j.text!=null)?j.text:JSON.stringify(j));
  const c=ctx[i].json;
  let s;
  try{
    const m=String(raw).replace(/```json|```/g,'').match(/\{[\s\S]*\}/);
    s=JSON.parse(m?m[0]:raw);
  }catch(e){ continue; }
  const score=Number(s.score)||0;
  const min=(c.score_minimo!=null)?c.score_minimo:40;
  if(score<min) continue;
  try{
    await this.helpers.httpRequest({method:'POST',url:URL+'/rest/v1/user_opportunities?on_conflict=user_id,opportunity_id',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json',Prefer:'resolution=ignore-duplicates'},body:[{user_id:c.user_id,opportunity_id:c.opportunity_id,codigo:c.codigo,score:score,viabilidad:s.viabilidad||'baja',accion:s.accion||'ignorar',resumen:(s.resumen||'').slice(0,2000),justificacion:(s.justificacion||'').slice(0,2000),riesgo:(s.riesgo||'').slice(0,2000),precio_sugerido_clp:(s.precio_sugerido_clp!=null?s.precio_sugerido_clp:null)}]});
    res.push({json:{user_id:c.user_id,codigo:c.codigo,score:score,accion:s.accion}});
  }catch(e){ console.error('Save '+c.codigo+': '+e.message); }
}
console.log('Scoring guardado: '+res.length);
return res.length?res:[{json:{message:'Sin nuevas oportunidades con score suficiente'}}];
